local x=np.flip(np.astype(np.arange(0,"int64"):reshape({2,0,3}),"bool"),1)
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"bool","42/(2, 0, 3)/bool/flip/0/out_same dtype")
deep(y:tolist(),{{},{}},"42/(2, 0, 3)/bool/flip/0/out_same values")
deep(x:tolist(),{{},{}},"42/(2, 0, 3)/bool/flip/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"c621fbcd16d92688","42/(2, 0, 3)/bool/flip/0/out_same pcg")
cases=cases+1; end
