local x=np.astype(np.arange(8,"int64"):reshape({2,1,4}),"int64")
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"int64","42/(2, 1, 4)/int64/plain/0/out_same dtype")
deep(y:tolist(),{{{4,1,2,3}},{{0,5,6,7}}},"42/(2, 1, 4)/int64/plain/0/out_same values")
deep(x:tolist(),{{{4,1,2,3}},{{0,5,6,7}}},"42/(2, 1, 4)/int64/plain/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"dbcd12c26eda1624","42/(2, 1, 4)/int64/plain/0/out_same pcg")
cases=cases+1; end
